<template>
  <v-hover>
    <template>
      <v-card
        flat
        color="cardBackgroundSecondary"
        class="card-container rounded-lg"
      >
        <div class="customer-icon">
          <v-icon color="white" size="50">{{ genderIcon }}</v-icon>
        </div>
        <div class="customer-detail">
          <div class="customer-description pr-10">
            <FormattedText
              :value="data.name"
              type="text-h6"
              class="mb-auto"
              className="font-weight-bold"
            />
            <FormattedText
              :value="
                `${getTranslatedText('customersView.customerCard.sales')}: ${
                  data.salesNumber
                }`
              "
              type="text-subtitle-2"
              className="customer-description-text font-weight-light"
            />
            <FormattedText
              :value="
                `${getTranslatedText(
                  'customersView.customerCard.totalExpense'
                )}: ${formatNumberFromDbToCurrency(data.expense)}`
              "
              type="text-subtitle-2"
              className="customer-description-text font-weight-light"
            />
            <FormattedText
              :value="
                `${getTranslatedText(
                  'customersView.customerCard.lastSaleDate'
                )}: ${
                  data.lastSaleDate === '-'
                    ? '-'
                    : formatDate(data.lastSaleDate)
                }`
              "
              type="text-subtitle-2"
              className="customer-description-text font-weight-light"
            />
          </div>
          <div class="customer-debt">
            <v-tooltip top color="customerPrimary">
              <template v-slot:activator="{ on, attrs }">
                <div v-bind="attrs" v-on="on">
                  <FormattedText
                    :value="formatNumberFromDbToCurrency(data.debt)"
                    :color="data.debt > 0 ? 'customerDebt' : 'textPrimary'"
                    type="text-h5"
                    className="font-weight-bold"
                  />
                </div>
              </template>
              <span>
                {{ getTranslatedText('customersView.customerCard.debt') }}
              </span>
            </v-tooltip>
          </div>
        </div>
      </v-card>
    </template>
  </v-hover>
</template>

<script>
import { getTranslatedText } from '@/tools/data'
import { formatDate } from '@/tools/dates'
import { formatNumberFromDbToCurrency } from '@/tools/numbersFormat'

import FormattedText from '@/components/shared/FormattedText'

export default {
  name: 'CustomerCard',
  components: { FormattedText },
  props: {
    data: {
      type: Object,
      required: true,
      default: () => ({
        name: 'Cliente 1',
        sales: 14,
        expense: 140000,
        debt: 5000,
      }),
    },
  },
  computed: {
    genderIcon() {
      switch (this.data.gender) {
        case 'Mujer':
          return 'mdi-human-female'
        case 'Hombre':
          return 'mdi-human-male'
        default:
          return 'mdi-human-non-binary'
      }
    },
  },
  methods: {
    getTranslatedText,
    formatDate,
    formatNumberFromDbToCurrency,
  },
}
</script>

<style lang="scss" scoped>
.card-container {
  display: flex;
  overflow: hidden;
  height: 90px;
  cursor: pointer;
  .customer-icon {
    display: flex;
    background-color: var(--v-accent-base);
    width: 90px;
    align-items: center;
    justify-content: center;
    border-top-right-radius: 0 !important;
  }
  .customer-detail {
    display: flex;
    justify-content: space-between;
    width: 100%;
    line-height: 0;
    .customer-description {
      display: flex;
      flex-direction: column;
      padding: 4px 14px 8px 14px;
      :deep(.customer-description-text) {
        line-height: 1;
      }
    }
    .customer-debt {
      display: flex;
      flex-direction: column;
      justify-content: center;
      height: 100%;
      padding-right: 14px;
    }
  }
}
</style>
