<template>
  <div class="fill-height">
    <PaginatedCards :config="paginatedCardsConfig" />
    <CustomerDetail v-if="customerDetailDialog.isOpen" />
  </div>
</template>

<script>
import { mapState, mapActions, mapGetters } from 'vuex'

import customersViewActions from '@/store/customersView/actions.types'

import setConfig from '@/components/CustomersView/CustomersList/PaginatedCards/config'
import PaginatedCards from '@/components/shared/PaginatedCards'
import CustomerDetail from '@/components/CustomersView/CustomerDetail'

export default {
  name: 'PaginatedCardsList',
  components: { PaginatedCards, CustomerDetail },
  computed: {
    ...mapState('app', ['windowSize', 'sidebarOpened']),
    ...mapState('customers', ['fetching']),
    ...mapState('customersView', ['filters', 'customerDetailDialog']),
    ...mapGetters('customers', ['getFilteredData']),
    paginatedCardsConfig() {
      return setConfig(
        {
          items: this.getFilteredData,
          filters: this.filters,
          windowHeight: this.windowSize.y,
          windowWidth: this.windowSize.x,
          sidebarOpened: this.sidebarOpened,
          currentCardComponent: 'CustomerCard',
          fetching: this.fetching,
        },
        {
          openCustomerDetailDialog: this.openCustomerDetailDialog,
        }
      )
    },
  },
  methods: {
    ...mapActions('customersView', [
      customersViewActions.setCustomerDetailDialogStatus,
    ]),
    openCustomerDetailDialog(client) {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'Customers',
        screen: 'CustomerCard',
        name: 'Open customer details',
      })
      const data = {
        isOpen: true,
        selectedCustomer: client,
      }
      this[customersViewActions.setCustomerDetailDialogStatus](data)
    },
  },
}
</script>
