const config = (state, methods) => {
  return {
    state,
    methods,
    groupClass: 'pr-4',
    groups: [
      {
        id: 'filters-group-01',
        controls: [
          {
            id: 'add-customer-control',
            type: 'button',
            class: 'pt-2 pl-1 pr-4',
            label: 'customersView.toolbar.buttons.addCustomer',
            icon: 'mdi-plus',
            color: 'customerPrimary',
            onClick: () => methods.openAddCustomerDialog(true),
          },
          {
            id: 'search-control',
            type: 'input',
            label: 'customersView.toolbar.searchField.label',
            placeholder: 'customersView.toolbar.searchField.placeholder',
            icon: 'mdi-magnify',
            backgroundColor: 'cardBackgroundSecondary',
            color: 'customerPrimary',
            ref: 'customer-input-search',
            group: 'search',
            onChange: value => methods.setSearchTerm(value),
          },
        ],
      },
    ],
  }
}

export default config
