import { required, decimal, minValue, maxValue } from 'vuelidate/lib/validators'

import {
  formatNumberFromDbToCurrency,
  formatNumberFromDb,
} from '@/tools/numbersFormat'

const setConfig = (state, methods) => ({
  state,
  methods,
  dialogData: {
    opened: state.opened,
    icon: 'mdi-cash-refund',
    title: 'customersView.customerDetails.payDebt',
    titleBackground: '#white',
    titleColor: 'textPrimary',
    persistent: true,
    buttonTextColor: {
      cancel: 'white',
      accept: 'white',
    },
    buttonColor: {
      cancel: 'accent',
      accept: 'primary',
    },
    messages: ['customersView.settleDebtDialog.message'],
    extraValuesMessages: [
      state.customer.name,
      formatNumberFromDbToCurrency(state.customer.debt),
    ],
    height: 300,
    maxWidth: 500,
    id: 'settle-debt-customer-form',
    onClickCancel: () => {
      methods.track({
        type: 'interaction',
        action: 'click',
        category: 'Customers',
        screen: 'SettleGeneralDebt',
        name: 'Cancel',
      })
      methods.closeDialog()
    },
    onClickAccept: () => methods.settleDebt(),
  },
  fields: [
    {
      id: 'settleGeneralDebtAmount',
      type: 'input',
      valueType: 'number',
      label: 'shared.amount',
      errorMessage: 'mainLayout.user.errorAmount',
      color: 'primaryColor',
      required: true,
      autofocus: true,
      validators: {
        required,
        decimal,
        minValue: minValue(0.1),
        maxValue: maxValue(formatNumberFromDb(state.customer.debt)),
      },
    },
  ],
  id: 'settle-debt-customer-form',
})

export default setConfig
