<template>
  <v-card-actions>
    <div>
      <v-btn
        color="error"
        ref="customerDetailDeleteButton"
        @click="deleteCustomer"
        v-track:click="{
          category: 'Customers',
          screen: 'CustomerDetails',
          name: 'Delete customer',
        }"
      >
        <v-icon color="white">mdi-delete-outline</v-icon>
        <FormattedText intl value="productsView.details.delete" color="white" />
      </v-btn>
      <DeleteCustomerDialog v-if="deleteCustomerDialog.isOpen" />
      <v-btn
        v-if="showPayDebtButton"
        color="primary"
        ref="customerDetailPayDebtButton"
        @click="payDebt"
        v-track:click="{
          category: 'Customers',
          screen: 'CustomerDetails',
          name: 'Pay general debt',
        }"
      >
        <v-icon color="white">mdi-cash-refund</v-icon>
        <FormattedText
          intl
          value="customersView.customerDetails.payDebt"
          color="white"
        />
      </v-btn>
      <SettleDebtDialog v-if="settleDebtDialog.isOpen" />
    </div>
    <v-spacer />
    <div class="text-right">
      <v-btn
        color="accent"
        ref="customerDetailCloseButton"
        @click="printOverview"
        v-track:click="{
          category: 'Customers',
          screen: 'CustomerDetails',
          name: 'Print summary',
        }"
      >
        <v-icon>mdi-printer</v-icon>
        <FormattedText
          intl
          value="customersView.customerDetails.printOverview"
          color="white"
        />
      </v-btn>
      <v-btn
        color="accent"
        ref="customerDetailCloseButton"
        @click="onClickClose"
        v-track:click="{
          category: 'Customers',
          screen: 'CustomerDetails',
          name: 'Close dialog',
        }"
      >
        <v-icon>mdi-close-circle-outline</v-icon>
        <FormattedText intl value="productsView.details.close" color="white" />
      </v-btn>
    </div>
    <div v-if="notInTestMode" id="ticket-overview-to-print" v-show="false">
      <TicketOverview
        :customer="customerDetailDialog.customerSelected"
        :enrolledCustomer="getEnrolledCustomer"
      />
    </div>
  </v-card-actions>
</template>

<script>
import { mapState, mapActions } from 'vuex'

import PRINTER_EVENTS from '@/config/events/printer'
import { testMode } from '@/config/env'

import rendererEventsService from '@/services/renderer/rendererEvents'

import customersViewActions from '@/store/customersView/actions.types'

import FormattedText from '@/components/shared/FormattedText'
import DeleteCustomerDialog from '@/components/CustomersView/CustomerDetail/Footer/DeleteCustomerDialog'
import SettleDebtDialog from '@/components/CustomersView/CustomerDetail/Footer/SettleDebtDialog'
import TicketOverview from '@/components/CustomersView/CustomerDetail/TicketOverview'

export default {
  name: 'CustomerDetailFooter',
  components: {
    FormattedText,
    DeleteCustomerDialog,
    SettleDebtDialog,
    TicketOverview,
  },
  computed: {
    ...mapState('customersView', [
      'customerDetailDialog',
      'deleteCustomerDialog',
      'settleDebtDialog',
    ]),
    ...mapState('app', ['addMarginTicket']),
    ...mapState('loyaltyProgram', {
      enrolledCustomers: state => state.data.enrolledCustomers,
    }),
    showPayDebtButton() {
      return (
        this.customerDetailDialog.customerSelected &&
        this.customerDetailDialog.customerSelected.debt > 0
      )
    },
    notInTestMode() {
      return !testMode
    },
    getEnrolledCustomer() {
      return this.enrolledCustomers.find(
        item =>
          item.customerId === this.customerDetailDialog.customerSelected.id
      )
    },
  },
  methods: {
    ...mapActions('customersView', [
      customersViewActions.setCustomerDetailDialogStatus,
      customersViewActions.setDeleteCustomerDialogStatus,
      customersViewActions.setSettleDebtDialogStatus,
    ]),
    onClickClose() {
      this[customersViewActions.setCustomerDetailDialogStatus]({
        isOpen: false,
      })
    },
    deleteCustomer() {
      this[customersViewActions.setDeleteCustomerDialogStatus](true)
    },
    payDebt() {
      this[customersViewActions.setSettleDebtDialogStatus](true)
    },
    printOverview() {
      rendererEventsService.send(PRINTER_EVENTS.channel, {
        event: PRINTER_EVENTS.events.printSale.name,
        data: {
          ticketToPrint: document.getElementById('ticket-overview-to-print')
            .innerHTML,
          addMarginTicket: this.addMarginTicket,
        },
      })
    },
  },
}
</script>
