<template>
  <v-card-title class="large-icon-title">
    <div>
      <FormattedText type="text-h6" class="mb-n2" className="customer-name">
        {{ selectedCustomer ? selectedCustomer.name : null }}
      </FormattedText>
      <FormattedText
        className="font-weight-bold customer-name"
        type="text-h5"
        :color="selectedCustomer.debt > 0 ? 'customerDebt' : 'textPrimary'"
      >
        {{
          `${getTranslatedText(
            'customersView.customerDetails.debt'
          )}: ${formatNumberFromDbToCurrency(selectedCustomer.debt)}`
        }}
      </FormattedText>
      <FormattedText
        className="font-italic"
        color="textSecondary"
        type="text-caption"
        class="customer-name"
      >
        {{
          `${getTranslatedText('customersView.customerDetails.sales')}: ${
            selectedCustomer.salesNumber
          }`
        }}
        <br />
        {{
          `${getTranslatedText(
            'customersView.customerDetails.pendingSales'
          )}: ${selectedCustomer.unpaidSalesNumber}`
        }}
      </FormattedText>
    </div>
    <div class="default-icon d-flex flex-column align-center">
      <div class="customer-icon">
        <v-icon color="white" x-large>{{ genderIcon }}</v-icon>
      </div>
      <v-chip
        v-if="isEnrolledCustomer(selectedCustomer.id)"
        color="primary"
        class="mb-n8 mt-3"
        small
        @click="goToLoyaltyProgram(selectedCustomer)"
        v-track:click="{
          category: 'Customers',
          screen: 'CustomerDetails',
          name: 'Go to enrolled customer',
        }"
      >
        {{ getTranslatedText('customersView.customerDetails.enrolled') }}
      </v-chip>
    </div>
  </v-card-title>
</template>

<script>
import { mapState } from 'vuex'

import { getTranslatedText } from '@/tools/data'
import { formatNumberFromDbToCurrency } from '@/tools/numbersFormat'

import FormattedText from '@/components/shared/FormattedText'

export default {
  name: 'CustomerDetailHeader',
  components: { FormattedText },
  computed: {
    ...mapState('customersView', {
      selectedCustomer: state => state.customerDetailDialog.customerSelected,
    }),
    ...mapState('loyaltyProgram', {
      enrolledCustomers: state => state.data.enrolledCustomers,
    }),
    genderIcon() {
      switch (this.selectedCustomer.gender) {
        case 'Mujer':
          return 'mdi-human-female'
        case 'Hombre':
          return 'mdi-human-male'
        default:
          return 'mdi-human-non-binary'
      }
    },
  },
  methods: {
    getTranslatedText,
    formatNumberFromDbToCurrency,
    goToLoyaltyProgram(selectedCustomer) {
      this.$router.push(`/app/loyalty-program?search=${selectedCustomer.phone}`)
    },
    isEnrolledCustomer(customerId) {
      return this.enrolledCustomers.some(
        customer => customer.customerId === customerId && customer.status === 1
      )
    },
  },
}
</script>
