<template>
  <DialogCard :config="dialogConfig.dialogData" />
</template>

<script>
import { mapState, mapActions } from 'vuex'

import { testMode } from '@/config/env'
import CUSTOMERS_DB_API_EVENTS from '@/config/events/databaseAPI/customersEvents'
import SYNCHRONIZATION_EVENTS from '@/config/events/synchronization'

import rendererEventsService from '@/services/renderer/rendererEvents'
import notificationsService from '@/services/renderer/notifications'

import customersActions from '@/store/customers/actions.types'
import loyaltyProgramActions from '@/store/loyaltyProgram/actions.types'
import customersViewActions from '@/store/customersView/actions.types'

import setDialogConfig from '@/components/CustomersView/CustomerDetail/Footer/DeleteCustomerDialog/config'

import DialogCard from '@/components/shared/DialogCard'

export default {
  name: 'DeleteCustomerDialog',
  components: { DialogCard },
  data() {
    return {
      deletingCustomer: false,
    }
  },
  computed: {
    ...mapState('customersView', [
      'deleteCustomerDialog',
      'customerDetailDialog',
    ]),
    ...mapState('account', { accountData: state => state.data }),
    dialogConfig() {
      return setDialogConfig(
        {
          opened: this.deleteCustomerDialog.isOpen,
        },
        {
          closeDialog: this.closeDialog,
          deleteCustomer: this.removeCustomer,
          track: this.$track,
        }
      )
    },
  },
  methods: {
    ...mapActions('customersView', [
      customersViewActions.setDeleteCustomerDialogStatus,
      customersViewActions.setCustomerDetailDialogStatus,
    ]),
    ...mapActions('customers', [customersActions.deleteCustomer]),
    ...mapActions('loyaltyProgram', [
      loyaltyProgramActions.deleteEnrolledCustomer,
    ]),
    closeDialog() {
      this[customersViewActions.setDeleteCustomerDialogStatus](false)
    },
    removeCustomer() {
      if (this.deletingCustomer === true) return
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'Customers',
        screen: 'DeleteCustomer',
        name: 'Confirm deletion',
      })
      this.deletingCustomer = true
      rendererEventsService.send(CUSTOMERS_DB_API_EVENTS.channel, {
        event: CUSTOMERS_DB_API_EVENTS.events.delete.name,
        data: {
          customer: this.customerDetailDialog.customerSelected,
          securityData: this.accountData.security,
          phoneCode: this.accountData.country.phoneCode,
          storeName: this.accountData.storeName,
        },
      })
    },
    onCustomerDeleted(customer) {
      rendererEventsService.send(SYNCHRONIZATION_EVENTS.channel, {
        event: SYNCHRONIZATION_EVENTS.events.deleteOperation.name,
        data: {
          entityData: customer.id,
          entityName: 'customers',
        },
      })
      this[loyaltyProgramActions.deleteEnrolledCustomer](customer.id)
      this[customersActions.deleteCustomer](customer.id)
      notificationsService.showSuccess(
        'notification.customers.deleted',
        this.$vuetify.lang,
        { timeout: 8000 }
      )
      this.closeDialog()
      this[customersViewActions.setCustomerDetailDialogStatus]({
        isOpen: false,
      })
      this.deletingCustomer = false
    },
    onCustomerDeletedError() {
      this.$track({
        type: 'system',
        action: 'error',
        category: 'Customers',
        screen: 'DeleteCustomer',
        name: 'Error deleting customer',
      })
      notificationsService.showError(
        'notification.customers.errorDeleting',
        this.$vuetify.lang,
        { timeout: 8000 }
      )
      this.closeDialog()
      this.deletingCustomer = false
    },
  },
  mounted() {
    if (testMode) return
    rendererEventsService.subscribe(
      CUSTOMERS_DB_API_EVENTS.replyChannel,
      async (event, payload) => {
        const events = CUSTOMERS_DB_API_EVENTS.events
        const customerSelected = this.customerDetailDialog.customerSelected
        const replies = {
          [events.delete.replies.success]: () => {
            if (customerSelected.unpaidSalesNumber > 0) {
              this.$track({
                type: 'system',
                action: 'delete_customer',
                category: 'Customers',
                screen: 'DeleteCustomer',
                name: 'Clean customer credit sales',
              })
              rendererEventsService.send(CUSTOMERS_DB_API_EVENTS.channel, {
                event: CUSTOMERS_DB_API_EVENTS.events.cleanCustomerSales.name,
                data: customerSelected.id,
              })
              return
            }
            this.$track({
              type: 'system',
              action: 'delete_customer',
              category: 'Customers',
              screen: 'DeleteCustomer',
              name: 'Create operation',
            })
            this.onCustomerDeleted(customerSelected)
          },
          [events.cleanCustomerSales.replies.success]: () => {
            this.onCustomerDeleted(customerSelected)
            this.$track({
              type: 'system',
              action: 'clean_credit_sales',
              category: 'Customers',
              screen: 'DeleteCustomer',
              name: 'Create operation',
            })
          },
          [events.delete.replies.error]: () => this.onCustomerDeletedError(),
          [events.cleanCustomerSales.replies.error]: () =>
            this.onCustomerDeletedError(),
        }
        if (payload.event in replies) replies[payload.event]()
      }
    )
  },
  beforeDestroy() {
    rendererEventsService.removeAllListeners(
      CUSTOMERS_DB_API_EVENTS.replyChannel
    )
  },
}
</script>
