<template>
  <ToolBar :config="componentConfig" />
</template>

<script>
import { mapState, mapActions, mapGetters } from 'vuex'

import helpCategories from '@/config/helpCategories'

import helpCenterViewActions from '@/store/helpCenterView/actions.types'
import productsViewActions from '@/store/productsView/action.types'

import config from '@/components/CustomersView/CustomersToolbar/Operations/config'
import ToolBar from '@/components/shared/ToolBar'

export default {
  name: 'CustomersOperations',
  components: {
    ToolBar,
  },
  data() {
    return {
      config,
    }
  },
  computed: {
    ...mapState('productsView', ['data', 'filters', 'component']),
    ...mapGetters('helpCenter', ['getFilteredData']),
    componentConfig: function() {
      return config(
        {
          component: this.component,
          videos: this.getFilteredData,
        },
        { setViewType: this[productsViewActions.setViewType] }
      )
    },
  },
  methods: {
    ...mapActions('productsView', [productsViewActions.setViewType]),
    ...mapActions('helpCenterView', [helpCenterViewActions.setVideoTypeFilter]),
  },
  mounted() {
    this[helpCenterViewActions.setVideoTypeFilter]([helpCategories.customers])
  },
  beforeDestroy() {
    this[helpCenterViewActions.setVideoTypeFilter]([])
  },
}
</script>
