import { formatNumberFromDbToCurrency } from '@/tools/numbersFormat'

import light from '@/themes/light'
import dark from '@/themes/dark'

export const config = (state, methods) => ({
  state,
  methods: {
    ...methods,
    onClick: client => methods.openCustomerDetailDialog(client),
    onDblClick: () => null,
  },
  title: 'customersView.listView.title',
  loaderColor: { light: light.productLoader, dark: dark.productLoader },
  titleClass: 'pl-2',
  icon: 'mdi-account-group-outline',
  page: 1,
  rowsPerPage: 6,
  rowOffsetHeight: 48,
  itemsPerRow: {
    withoutDetail: {
      lg: 3,
      xl: 4,
    },
  },
  headers: [
    {
      text: methods.context.$vuetify.lang.t(
        '$vuetify.customersView.listView.sortBy.name'
      ),
      align: 'start',
      value: 'name',
      format: item => item,
    },
    {
      text: methods.context.$vuetify.lang.t(
        '$vuetify.customersView.listView.sortBy.sales'
      ),
      value: 'salesNumber',
      format: item => item,
    },
    {
      text: methods.context.$vuetify.lang.t(
        '$vuetify.customersView.listView.sortBy.expense'
      ),
      value: 'expense',
      format: item => formatNumberFromDbToCurrency(item),
    },
    {
      text: methods.context.$vuetify.lang.t(
        '$vuetify.customersView.listView.sortBy.debt'
      ),
      align: 'end',
      value: 'debt',
      format: item => formatNumberFromDbToCurrency(item),
    },
  ],
  sortBy: 'name',
  sortDesc: false,
  isClickable: true,
})

export default config
