const config = (state, methods) => ({
  state,
  methods,
  groups: [
    {
      id: 'operations-group-01',
      controls: [
        {
          id: 'help-dropdown-control',
          type: 'buttonDropdown',
          label: 'productsView.toolbar.buttons.help',
          icon: 'mdi-school',
          color: 'help',
          textColor: 'textPrimary',
          items: state.videos,
          listItemType: 'VideoListItem',
        },
        {
          id: 'list-type-control',
          type: 'button',
          label:
            state.component !== 'PaginatedCards'
              ? 'productsView.toolbar.buttons.cardsViewType'
              : 'productsView.toolbar.buttons.tableViewType',
          icon:
            state.component !== 'PaginatedCards'
              ? 'mdi-card-bulleted'
              : 'mdi-table',
          color: 'accent',
          onClick: () => {
            // methods.resetScannerStatus()
            state.component !== 'PaginatedCards'
              ? methods.setViewType('PaginatedCards')
              : methods.setViewType('PaginatedTable')
          },
        },
      ],
    },
  ],
})

export default config
