<template>
  <v-dialog
    v-model="customerDetailDialog.isOpen"
    max-width="660"
    :overlay-opacity="0.15"
    content-class="default-dialog"
    @click:outside="onClickOutside"
  >
    <v-card
      flat
      :class="{ collapsed: customerDetailDialog.isOpen }"
      :height="700"
      color="cardBackgroundPrimary"
    >
      <Header />
      <v-card-text>
        <Tabs
          :tabs="tabs"
          backgroundColor="cardBackgroundPrimary"
          textColor="accent"
          track-screen="CustomerDetails"
        />
      </v-card-text>
      <OperationDetail v-if="operationDetailDialog.isOpen" />
      <Footer />
    </v-card>
  </v-dialog>
</template>

<script>
import { mapState, mapActions } from 'vuex'

import { testMode } from '@/config/env'
import { cashOperation } from '@/config/storeMapper'
import CASH_OPERATIONS_DB_API_EVENTS from '@/config/events/databaseAPI/cashOperationsEvents'

import { getTranslatedText } from '@/tools/data'
import { mapStoreObject } from '@/tools/data'

import rendererEventsService from '@/services/renderer/rendererEvents'
import notificationsService from '@/services/renderer/notifications'

import customersViewActions from '@/store/customersView/actions.types'
import operationsViewActions from '@/store/operationsView/actions.types'

import Header from '@/components/CustomersView/CustomerDetail/Header'
import Tabs from '@/components/shared/Tabs'
import CreditSalesTab from '@/components/CustomersView/CustomerDetail/CreditSalesTab'
import DetailsTab from '@/components/CustomersView/CustomerDetail/DetailsTab'
import Footer from '@/components/CustomersView/CustomerDetail/Footer'
import SalesTab from '@/components/CustomersView/CustomerDetail/SalesTab'
import OperationDetail from '@/components/OperationsView/OperationDetail'

export default {
  name: 'CustomerDetail',
  components: { OperationDetail, Header, Tabs, Footer },
  data() {
    return {
      tabs: [
        {
          id: 0,
          name: this.getTranslatedText(
            'customersView.customerDetails.pendingSales'
          ),
          icon: 'mdi-cart',
          component: CreditSalesTab,
        },
        {
          id: 1,
          name: this.getTranslatedText('customersView.customerDetails.sales'),
          icon: 'mdi-chart-bar',
          component: SalesTab,
        },
        {
          id: 2,
          name: this.getTranslatedText('customersView.customerDetails.details'),
          icon: 'mdi-clipboard-check',
          component: DetailsTab,
        },
      ],
    }
  },
  computed: {
    ...mapState('customers', ['data']),
    ...mapState('customersView', ['customerDetailDialog']),
    ...mapState('operationsView', ['operationDetailDialog']),
  },
  methods: {
    getTranslatedText,
    ...mapActions('customersView', [
      customersViewActions.setCustomerDetailDialogStatus,
    ]),
    ...mapActions('operationsView', [
      operationsViewActions.setOperationDetailDialogStatus,
    ]),
    onClickOutside() {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'Customers',
        screen: 'CustomerDetails',
        name: 'Close dialog',
      })
      this[customersViewActions.setCustomerDetailDialogStatus]({
        isOpen: false,
      })
    },
    cashOperationsListener(event, payload) {
      const events = CASH_OPERATIONS_DB_API_EVENTS.events
      const replies = {
        [events.getByOperationTypeAndRelatedId.replies.success]: () =>
          rendererEventsService.send(CASH_OPERATIONS_DB_API_EVENTS.channel, {
            event: CASH_OPERATIONS_DB_API_EVENTS.events.getOperationDetail.name,
            data: {
              operation: mapStoreObject(payload.data, cashOperation),
              customers: this.data.customers,
            },
          }),
        [events.getOperationDetail.replies.success]: () =>
          this[operationsViewActions.setOperationDetailDialogStatus]({
            isOpen: true,
            operationSelected: payload.data,
          }),
        [events.getByOperationTypeAndRelatedId.replies.error]: () =>
          notificationsService.showError(
            payload.data.errorMsg,
            this.$vuetify.lang
          ),
        [events.getOperationDetail.replies.error]: () =>
          notificationsService.showError(
            'notification.operations.cantOpenDetail',
            this.$vuetify.lang
          ),
      }
      if (payload.event in replies) replies[payload.event]()
    },
  },
  created() {
    if (testMode) return
    rendererEventsService.subscribe(
      CASH_OPERATIONS_DB_API_EVENTS.replyChannel,
      this.cashOperationsListener
    )
  },
  beforeDestroy() {
    rendererEventsService.removeListener(
      CASH_OPERATIONS_DB_API_EVENTS.replyChannel,
      this.cashOperationsListener
    )
  },
}
</script>
