const setConfig = (state, methods) => ({
  state,
  methods,
  dialogData: {
    opened: state.opened,
    icon: 'mdi-alert-circle',
    title: 'customersView.deleteCustomerDialog.title',
    titleBackground: '',
    titleColor: 'textPrimary',
    persistent: true,
    buttonTextColor: {
      cancel: 'white',
      accept: 'white',
    },
    buttonColor: {
      cancel: 'accent',
      accept: 'primary',
    },
    messages: ['customersView.deleteCustomerDialog.message'],
    height: 225,
    maxWidth: 500,
    onClickCancel: () => {
      methods.track({
        type: 'interaction',
        action: 'click',
        category: 'Customers',
        screen: 'DeleteCustomer',
        name: 'Cancel',
      })
      methods.closeDialog()
    },
    onClickAccept: () => methods.deleteCustomer(),
  },
})

export default setConfig
