<template>
  <v-data-table
    id="data-table-container"
    ref="tableContainer"
    :headers="config.headers"
    :items="config.state.items"
    :items-per-page.sync="rowsPerPage"
    :page.sync="page"
    :sort-by="config.sortBy"
    :sort-desc="config.sortDesc"
    :loading="config.state.fetching"
    item-key="upc"
    hide-default-footer
    class="d-flex flex-column paginated-table"
    v-bind="customFunctions"
    @update:options="onSort"
    :dense="config.dense"
  >
    <!-- Loader -->
    <template v-slot:loading>
      <v-overlay
        :value="config.state.fetching"
        absolute
        class="paginated-table__fetching"
        opacity="0.15"
      >
        <SyncLoader :color="loaderColor" />
      </v-overlay>
    </template>
    <!-- Table header -->
    <template v-slot:top v-if="!config.hideTop">
      <div id="data-table-header-custom" ref="tableHeaderCustom">
        <div class="d-flex justify-space-between paginated-table__header">
          <div class="d-flex align-center pb-6">
            <v-icon color="primary" large>{{ config.icon }}</v-icon>
            <FormattedText
              intl
              type="title"
              color="textPrimary"
              :value="config.title"
              :class="config.titleClass ? config.titleClass : ''"
            />
            <slot name="headerLeft" />
          </div>
          <div class="d-flex align-center pb-6">
            <div
              v-if="
                'filters' in config.state &&
                  'superCategories' in config.state.filters
              "
              class="d-flex"
            >
              <div
                v-for="category in config.state.filters.superCategories"
                :key="category"
                class="pr-3"
              >
                <v-chip color="productPrimary" text-color="white">
                  <v-avatar left>
                    <v-icon>mdi-tag-outline</v-icon>
                  </v-avatar>
                  {{ getTranslatedText(`superCategories.${category}`) }}
                </v-chip>
              </div>
            </div>
            <v-chip
              v-if="groupIcon.length > 0"
              class="ma-2"
              color="primary"
              text-color="white"
            >
              <v-avatar left>
                <v-icon middle>{{ groupIcon[0].icon }}</v-icon>
              </v-avatar>
              <FormattedText intl color="white" :value="groupIcon[0].title" />
            </v-chip>
          </div>
        </div>
      </div>
    </template>
    <!-- Table content -->
    <template v-slot:item="{ item, index }">
      <slot v-if="$scopedSlots.item" name="item" :item="item" />
      <tr
        v-else
        :class="getRowClass(item)"
        :style="getRowStyle(item)"
        @click="onClickCard(item)"
      >
        <td
          v-for="(column, indexRow) in config.headers"
          :key="`row-table-${indexRow}`"
          :align="column.align"
        >
          <slot
            v-if="$scopedSlots[column.value]"
            :name="column.value"
            :item="item"
          />
          <div
            v-else
            :class="['d-flex', column.align ? `justify-${column.align}` : '']"
          >
            <v-icon
              v-if="column.icon"
              class="pr-1"
              size="20"
              :color="
                'color' in column.icon(item[column.value])
                  ? column.icon(item[column.value]).color
                  : undefined
              "
            >
              {{ column.icon(item[column.value]).icon }}
            </v-icon>
            {{ getValueToShow(item, column, index) }}
          </div>
        </td>
      </tr>
    </template>
    <template v-slot:footer>
      <v-row
        class="no-gutters mt-auto py-2 shrink"
        align="center"
        justify="end"
      >
        <div v-if="config.state.items.length > 0">
          <v-spacer></v-spacer>
          <div class="px-0 pb-4">
            <span class="mr-4 grey--text">
              {{ getTranslatedText('dataIterator.pageText', page) }}
              <span
                v-text="numberOfPages"
                class="font-weight-bold primary--text"
              ></span>
            </span>
            <v-btn
              small
              dark
              rounded
              color="primary"
              class="mr-1"
              @click="formerPage"
              v-track:click="{
                category: $route.name,
                screen: 'PaginatedTable',
                name: 'Go to previous page',
              }"
            >
              <v-icon>mdi-chevron-left</v-icon>
            </v-btn>
            <v-btn
              small
              dark
              rounded
              color="primary"
              class="ml-1"
              @click="nextPage"
              v-track:click="{
                category: $route.name,
                screen: 'PaginatedTable',
                name: 'Go to next page',
              }"
            >
              <v-icon>mdi-chevron-right</v-icon>
            </v-btn>
          </div>
        </div>
      </v-row>
    </template>
  </v-data-table>
</template>

<script>
import { isNil } from 'ramda'
import { SyncLoader } from '@saeris/vue-spinners'

import { getObjectCopy, getTranslatedText } from '@/tools/data'

import FormattedText from '@/components/shared/FormattedText'

export default {
  name: 'PaginatedTable',
  components: { FormattedText, SyncLoader },
  props: {
    config: {
      type: Object,
      required: true,
    },
  },
  data() {
    return {
      page: this.config.page,
      rowsPerPage: this.config.rowsPerPage,
      clicks: 0,
      timer: null,
    }
  },
  computed: {
    numberOfPages() {
      return Math.ceil(this.config.state.items.length / this.rowsPerPage)
    },
    groupIcon() {
      if (!('groups' in this.config)) return []
      return this.config.groups.filter(
        item => item.id === this.config.state.filters.group
      )
    },
    loaderColor() {
      const { light, dark } = this.config.loaderColor
      return this.$vuetify.theme.dark ? dark : light
    },
    customFunctions() {
      const customFunctions = {}
      if (this.config.customSort) {
        customFunctions['custom-sort'] = this.config.customSort
      }
      return customFunctions
    },
  },
  methods: {
    getTranslatedText,
    nextPage() {
      if ('resetScannerStatus' in this.config.methods)
        this.config.methods.resetScannerStatus()
      if (this.page + 1 <= this.numberOfPages) this.page += 1
    },
    formerPage() {
      if ('resetScannerStatus' in this.config.methods)
        this.config.methods.resetScannerStatus()
      if (this.page - 1 >= 1) this.page -= 1
    },
    getRowsPerPage() {
      const container = this.$refs.tableContainer.$el.offsetHeight
      const minItemHeight = this.config.rowOffsetHeight
      const containerHeight = parseInt(container, 0)
      const tableTopHeight = this.$refs.tableHeaderCustom?.offsetHeight || 0
      this.rowsPerPage = Math.floor(
        Math.max(
          containerHeight - 2 * minItemHeight - tableTopHeight,
          minItemHeight
        ) / minItemHeight
      )
    },
    onClickCard(item) {
      const cleanItem = getObjectCopy(item)
      this.clicks++
      if (this.clicks === 1) {
        var self = this
        this.timer = setTimeout(() => {
          self.clicks = 0
          this.config.methods.onClick(cleanItem)
        }, 200)
      } else {
        clearTimeout(this.timer)
        this.config.methods.onDblClick(cleanItem)
        this.clicks = 0
      }
    },
    onSort() {
      if ('resetScannerStatus' in this.config.methods)
        this.config.methods.resetScannerStatus()
    },
    getRowClass(item) {
      let classes = ''
      if (!isNil(item.isStoreInventory)) {
        classes =
          item.isStoreInventory === 1 ? 'isStoreInventory' : 'isMlpProduct'
      }
      if (this.config.isClickable) classes += ' pointer'
      return classes.trim()
    },
    getRowStyle(item) {
      return this.config.rowStyle ? this.config.rowStyle(item) : ''
    },
    getValueToShow(row, column, index) {
      if (isNil(row.isStoreInventory)) {
        const indexInArray = index + (this.page - 1) * (this.rowsPerPage || 0)
        return column.format(row[column.value], row, indexInArray)
      }
      return row.isStoreInventory === 1 ||
        column.value === 'name' ||
        column.value === 'upc'
        ? column.format(row[column.value], row)
        : ''
    },
  },
  watch: {
    'config.state.windowHeight': function(newValue, oldValue) {
      if (oldValue !== newValue) {
        this.getRowsPerPage()
      }
    },
  },
  mounted() {
    // Wait container render finish
    setTimeout(() => {
      this.getRowsPerPage()
    }, 100)
  },
}
</script>

<style lang="scss" scoped>
.paginated-table {
  background-color: var(--v-mainBackground-base) !important;
  height: 100%;
  overflow: hidden;
  .paginated-table__fetching {
    height: 100%;
    display: flex;
    justify-content: center;
    align-items: center;
    flex-direction: column;
  }
  .paginated-table__header {
    height: 90px;
  }
}

#data-iterator-container {
  align-content: flex-start;
}
.fade-enter, .fade-leave-to /* .fade-leave-active below version 2.1.8 */ {
  opacity: 0;
}

.slide-in-enter {
  opacity: 0;
  transform: scale(0.8);
}
.slide-in-enter-active {
  transition: all 0.4s ease;
}
.isStoreInventory {
  color: var(--v-textPrimary-base);
  font-weight: 500;
}
.isMlpProduct {
  color: grey;
}
</style>
