<template>
  <div v-if="customer.sales.length > 0" class="pt-4 tab-color">
    <ScrollContainer height="380px" max-height="380px">
      <v-card
        v-for="sale in customer.sales"
        :key="sale._id"
        flat
        color="cardBackgroundSecondary"
        class="rounded-lg py-3 px-4 mb-2 d-flex justify-space-between"
        @click="openOperationDetailDialog(sale)"
        v-track:click="{
          category: 'Customers',
          screen: 'CustomerDetails',
          name: 'Open sale details',
        }"
      >
        <FormattedText :value="formatSaleDate(sale.sale_date)" type="text-h6" />
        <FormattedText
          :value="formatNumberFromDbToCurrency(sale.final_price)"
          :color="
            !sale.paid && sale.receivable.amount - sale.receivable.settled > 0
              ? 'customerDebt'
              : 'textPrimary'
          "
          type="text-h6"
          className="font-weight-bold"
        />
      </v-card>
    </ScrollContainer>
  </div>
  <AlertNoDataToShow v-else />
</template>

<script>
import { mapState } from 'vuex'

import { idOperations } from '@/config/cashOperationsVariables'
import CASH_OPERATIONS_DB_API_EVENTS from '@/config/events/databaseAPI/cashOperationsEvents'

import { getTranslatedText } from '@/tools/data'
import { formatNumberFromDbToCurrency } from '@/tools/numbersFormat'
import { formatDate, getDayOfWeek, toDate } from '@/tools/dates'

import rendererEventsService from '@/services/renderer/rendererEvents'

import FormattedText from '@/components/shared/FormattedText'
import AlertNoDataToShow from '@/components/shared/AlertNoDataToShow'
import ScrollContainer from '@/components/shared/ScrollContainer'

export default {
  name: 'CustomerSalesTab',
  components: { ScrollContainer, AlertNoDataToShow, FormattedText },
  computed: {
    ...mapState('customersView', {
      customer: state => state.customerDetailDialog.customerSelected,
    }),
  },
  methods: {
    toDate,
    formatNumberFromDbToCurrency,
    getTranslatedText,
    formatSaleDate(saleDate) {
      const dayOfWeek = this.getTranslatedText(
        `dates.dayOfWeek.${getDayOfWeek(saleDate)}`
      )
      return `${dayOfWeek}, ${formatDate(saleDate)}`
    },
    openOperationDetailDialog(sale) {
      rendererEventsService.send(CASH_OPERATIONS_DB_API_EVENTS.channel, {
        event:
          CASH_OPERATIONS_DB_API_EVENTS.events.getByOperationTypeAndRelatedId
            .name,
        data: {
          type:
            'receivable' in sale
              ? idOperations.ID_OPERATION_CREDIT_SALE
              : idOperations.ID_OPERATION_CASH_SALE,
          relatedId: sale._id,
        },
      })
    },
  },
}
</script>

<style lang="scss" scoped>
.tab-color {
  height: 100%;
  background-color: var(--v-cardBackgroundPrimary-base);
}
</style>
