<template>
  <ToolBar :config="componentConfig" />
</template>

<script>
import { mapState, mapActions } from 'vuex'

import customersViewActions from '@/store/customersView/actions.types'

import config from '@/components/CustomersView/CustomersToolbar/Filters/config'
import ToolBar from '@/components/shared/ToolBar'

export default {
  name: 'CustomersFilter',
  components: {
    ToolBar,
  },
  data() {
    return {
      config,
    }
  },
  computed: {
    ...mapState('customersView', ['filters']),
    componentConfig: function() {
      return config(
        { filters: this.filters },
        {
          setSearchTerm: this[customersViewActions.setSearchTermFilter],
          openAddCustomerDialog: this.setAddCustomerDialogStatus,
        }
      )
    },
  },
  methods: {
    ...mapActions('customersView', [
      customersViewActions.setAddCustomerDialogStatus,
      customersViewActions.setSearchTermFilter,
    ]),
  },
}
</script>
