<template>
  <v-container fluid class="customers-view" id="customers-view">
    <!-- View toolbar  -->
    <v-row no-gutters>
      <v-col cols="12" v-if="showLoyaltyBanner">
        <Banner id="loyalty-banner" :config="bannerConfig" />
      </v-col>
      <v-col
        class="customers-view__filter-toolbar px-6 pt-6"
        id="customers-view__filter-toolbar"
      >
        <CustomersToolBar />
      </v-col>
    </v-row>
    <!-- List view -->
    <v-row no-gutters>
      <v-col
        class="customers-view__customers-list"
        id="customers-view__customers-list"
        :style="{
          height: `calc(100vh - ${getCustomersListStyles}px)`,
        }"
      >
        <CustomersList />
      </v-col>
    </v-row>
  </v-container>
</template>

<script>
import { mapState, mapActions, mapGetters } from 'vuex'

import ENTITIES_EVENTS from '@/config/events/databaseAPI/entitiesEvents'

import { getAppLayoutHeaderAndFooterHeight } from '@/tools/view'

import rendererEventsService from '@/services/renderer/rendererEvents'

import customersActions from '@/store/customers/actions.types'
import customersViewActions from '@/store/customersView/actions.types'

import CustomersToolBar from '@/components/CustomersView/CustomersToolbar'
import CustomersList from '@/components/CustomersView/CustomersList'
import Banner from '@/components/shared/Banner'

import setBannerConfig from '@/components/CustomersView/config'

export default {
  name: 'Customers',
  components: { CustomersToolBar, CustomersList, Banner },
  data() {
    return {
      layoutCommonElementsHeight: 0,
    }
  },
  computed: {
    ...mapState('usersView', ['selectedUser']),
    ...mapGetters('account', ['getLoyaltyProgram']),
    getCustomersListStyles() {
      return this.layoutCommonElementsHeight
    },
    showLoyaltyBanner() {
      return (
        !this.getLoyaltyProgram.loyaltyProgramActived &&
        this.selectedUser.id === 1
      )
    },
    bannerConfig() {
      return setBannerConfig(
        {},
        {
          configLotaltyProgram: this.configLotaltyProgram,
        }
      )
    },
  },
  methods: {
    ...mapActions('customers', [
      customersActions.fetchCustomers,
      customersActions.setCustomersFetching,
      customersActions.setCustomersError,
    ]),
    ...mapActions('customersView', [
      customersViewActions.setCustomerDetailDialogStatus,
    ]),
    configLotaltyProgram() {
      this.$router.push({ name: 'LoyaltyProgramConfig' })
    },
    getLayoutHeight() {
      const layoutComponentsHeight = getAppLayoutHeaderAndFooterHeight(
        'customers-view'
      )
      const customersViewToolbar = document.getElementById(
        'customers-view__filter-toolbar'
      ).offsetHeight

      this.layoutCommonElementsHeight =
        layoutComponentsHeight + customersViewToolbar
      if (this.showLoyaltyBanner) {
        const loyaltyBanner = document.getElementById('loyalty-banner')
          .offsetHeight
        this.layoutCommonElementsHeight += loyaltyBanner
      }
    },
    async customersListener(event, payload) {
      const getAllReplies = ENTITIES_EVENTS.events.getAllByEntities.replies
      const replies = {
        [`${getAllReplies.success}-fetchCustomers`]: () =>
          this[customersActions.fetchCustomers](payload.data),
        [`${getAllReplies.error}-fetchCustomers`]: () => {
          this[customersActions.setCustomersError](payload.data)
          this[customersActions.setCustomersFetching](false)
        },
      }
      if (payload.event in replies) replies[payload.event]()
      this.$loading.hide()
    },
    sendFetchCustomers() {
      this[customersActions.setCustomersFetching](true)
      this.$loading.show('loadCustomers')
      rendererEventsService.send(ENTITIES_EVENTS.channel, {
        event: ENTITIES_EVENTS.events.getAllByEntities.name,
        data: {
          entitiesToGet: ['sales', 'customers', 'receivables'],
          replyName: 'fetchCustomers',
        },
      })
    },
  },
  mounted() {
    this.$root.$on('updateCustomers', this.sendFetchCustomers)
    rendererEventsService.subscribe(
      ENTITIES_EVENTS.replyChannel,
      this.customersListener
    )
    this.sendFetchCustomers()
    this.getLayoutHeight()
  },
  beforeDestroy() {
    this.$root.$off('updateCustomers', this.sendFetchCustomers)
    rendererEventsService.removeListener(
      ENTITIES_EVENTS.replyChannel,
      this.customersListener
    )
    this[customersViewActions.setCustomerDetailDialogStatus]({
      isOpen: false,
    })
  },
}
</script>

<style lang="scss" scoped>
$window-status: 'default', 'minimum';

.customers-view {
  height: 100%;
  .customers-view__filter-toolbar {
    background-color: var(--v-mainBackground-base);
  }
  .customers-view__products-list {
    width: 100%;
  }
}
</style>
