import CustomerCard from '@/components/shared/CustomerCard'

import light from '@/themes/light'
import dark from '@/themes/dark'

export const setConfig = (state, methods) => ({
  state,
  methods: {
    ...methods,
    onClick: client => methods.openCustomerDetailDialog(client),
    onDblClick: () => null,
  },
  containerRef: 'customers-view__customers-list',
  title: 'customersView.listView.title',
  titleClass: 'pl-2',
  icon: 'mdi-account-group-outline',
  loaderColor: { light: light.productLoader, dark: dark.productLoader },
  isDetail: false,
  sort: {
    by: [
      { prop: 'name', text: 'customersView.listView.sortBy.name' },
      { prop: 'debt', text: 'customersView.listView.sortBy.debt' },
      {
        prop: 'salesNumber',
        text: 'customersView.listView.sortBy.sales',
      },
      { prop: 'expense', text: 'customersView.listView.sortBy.expense' },
    ],
    sortBy: 'name',
    sortDesc: false,
    iconColor: 'accent',
  },
  rowsPerPage: 4,
  page: 1,
  cardComponents: {
    CustomerCard: {
      cardOffsetHeight: 107,
      component: CustomerCard,
      itemsPerRow: {
        small: 2,
        medium: 2,
        large: 3,
        extraLarge: 4,
      },
    },
  },
  noDataMessage: {
    icon: 'mdi-plus-circle',
    messages: [
      'customersView.listView.noData.firstMessage',
      'customersView.listView.noData.secondMessage',
    ],
  },
})

export default setConfig
