<template>
  <div class="ticket-to-print">
    <img class="centered" width="150" :src="ticketLogo" />
    <p class="large-font">
      {{ storeName }}
      <br />
      <strong>
        {{ getTranslatedText('customersView.ticketOverview.customer') }}:
      </strong>
      <strong>{{ customer.name }}</strong
      ><br />
      {{ getTranslatedText('customersView.ticketOverview.date') }}:
      {{ overviewDate }}
    </p>

    <p></p>
    <p class="large-font">
      {{ getTranslatedText('customersView.ticketOverview.creditLimit') }}:
      {{ formatNumberFromDbToCurrency(customer.debtLimit) }}<br />
      {{ getTranslatedText('customersView.ticketOverview.unpaidSales') }}:
      {{ customer.unpaidSalesNumber }}<br />
    </p>
    <span>
      <strong>
        {{ getTranslatedText('customersView.ticketOverview.debts') }}
      </strong>
    </span>
    <!-- Unpaid sales list -->
    <div v-if="get10LastUnpaidSales.length > 0">
      <div class="sale-container">
        <div class="sale-detail">
          <span>
            {{ getTranslatedText('customersView.ticketOverview.saleDate') }}:
          </span>
          <span>
            {{ getTranslatedText('customersView.ticketOverview.total') }}:
          </span>
        </div>
      </div>
      <p class="small-font">
        ----------------------------------------------------------
      </p>
      <div
        v-for="sale in get10LastUnpaidSales"
        :key="sale._id"
        class="sale-container"
      >
        <div class="sale-detail">
          <span>{{ formatDate(sale.sale_date) }}</span>
          <span>
            {{
              formatNumberFromDbToCurrency(
                sale.receivable.amount - sale.receivable.settled
              )
            }}
          </span>
        </div>
      </div>
      <p class="small-font">
        ----------------------------------------------------------
      </p>
      <p class="total-row">
        {{ getTranslatedText('customersView.ticketOverview.totalDebt') }}:
        <strong>{{ formatNumberFromDbToCurrency(customer.expense) }}</strong>
      </p>
    </div>
    <div v-else>
      <p class="large-font">
        {{ getTranslatedText('customersView.ticketOverview.noUnpaidSale') }}
      </p>
    </div>
    <!-- Loyalty -->
    <div v-if="enrolledCustomer !== null">
      <span>
        <strong>
          {{ getTranslatedText('customersView.ticketOverview.loyaltyProgram') }}
        </strong>
      </span>
      <p class="large-font">
        {{ getTranslatedText('customersView.ticketOverview.objective') }}:
        {{ formatNumberFromDbToCurrency(enrolledCustomer.amount) }}<br />
        {{ getTranslatedText('customersView.ticketOverview.pendingAmount') }}:
        {{ formatNumberFromDbToCurrency(enrolledCustomer.amountPending) }}<br />
        {{ getTranslatedText('customersView.ticketOverview.nextObjective') }}:
        {{ formatNumberFromDbToCurrency(rewardAmount) }}<br />
      </p>
    </div>
  </div>
</template>

<script>
import { mapState } from 'vuex'

import tiendatekLogoBase64 from '@/config/tiendatekLogoBase64'

import { getTranslatedText } from '@/tools/data'
import { getNow, formatDate } from '@/tools/dates'
import { formatNumberFromDbToCurrency } from '@/tools/numbersFormat'

export default {
  name: 'TicketOverview',
  props: {
    customer: {
      type: Object,
      required: true,
    },
    enrolledCustomer: {
      type: Object,
      default: null,
    },
  },
  computed: {
    ...mapState('account', {
      storeName: state => state.data.storeName,
      rewardAmount: state => state.data.loyaltyProgram.rewardAmount,
    }),
    ticketLogo() {
      return `data:image/jpg;base64,${tiendatekLogoBase64}`
    },
    overviewDate() {
      return formatDate(getNow(false))
    },
    get10LastUnpaidSales() {
      return this.customer.unpaidSales.slice(-10)
    },
  },
  methods: {
    getTranslatedText,
    formatNumberFromDbToCurrency,
    formatDate,
  },
}
</script>

<style lang="scss" scoped>
.ticket-to-print {
  width: 155px;
  max-width: 155px;
  .large-font {
    font-size: 12px;
  }
  .medium-font {
    font-size: 10px;
  }
  .small-font {
    font-size: 8px;
  }
  .centered {
    text-align: center;
    align-content: center;
  }
  .sale-container {
    display: flex;
    flex-direction: column;
    font-size: 10px;
    .sale-detail {
      display: flex;
      justify-content: space-between;
    }
  }
  .total-row {
    font-size: 12px;
    display: flex;
    justify-content: space-between;
  }
}
</style>
