<template>
  <v-card flat color="cardBackgroundPrimary">
    <div class="pt-6 d-flex flex-column">
      <v-card class="pa-0 rounded-widget" color="cardBackgroundSecondary" flat>
        <div class="py-1 pl-5 pr-1 d-flex widget-title">
          <v-icon color="accent">
            mdi-card-account-details-outline
          </v-icon>
          <FormattedText
            intl
            type="text-body-1"
            color="textOverBackground"
            value="customersView.customerDetails.clientDetails"
            class="pl-2 pt-1"
            className="font-weight-bold"
          />
        </div>
        <v-container class="pa-0">
          <div class="d-flex flex-column pa-4">
            <div
              v-for="(row, index) in widgetConfig.singleWidgets"
              :key="index"
              class="mb-3"
            >
              <div class="d-flex justify-space-between">
                <div v-for="widget in row" :key="widget.id">
                  <component
                    :is="widget.type"
                    :config="widget"
                    :class="widget.extraClasses"
                  />
                </div>
              </div>
            </div>
          </div>
        </v-container>
      </v-card>
    </div>
  </v-card>
</template>

<script>
import { mapState, mapActions } from 'vuex'

import { testMode } from '@/config/env'
import CUSTOMERS_DB_API_EVENTS from '@/config/events/databaseAPI/customersEvents'
import SYNCHRONIZATION_EVENTS from '@/config/events/synchronization'

import rendererEventsService from '@/services/renderer/rendererEvents'

import notificationsService from '@/services/renderer/notifications'

import customersActions from '@/store/customers/actions.types'
import customersViewActions from '@/store/customersView/actions.types'
import loyaltyProgramActions from '@/store/loyaltyProgram/actions.types'

import setConfig from '@/components/CustomersView/CustomerDetail/DetailsTab/config'
import FormattedText from '@/components/shared/FormattedText'

export default {
  name: 'CustomerDetailsTab',
  components: { FormattedText },
  data() {
    return {
      isEnrolledCustomer: false,
    }
  },
  computed: {
    ...mapState('customersView', ['customerDetailDialog']),
    ...mapState('loyaltyProgram', {
      enrolledCustomers: state => state.data.enrolledCustomers,
    }),
    widgetConfig() {
      return setConfig(
        {
          customer: this.customerDetailDialog.customerSelected,
          phoneNumber: this.customerDetailDialog.customerSelected.phone,
          name: this.customerDetailDialog.customerSelected.name,
          isEnrolledCustomer: this.isEnrolledCustomer,
        },
        {
          updateSelectedCustomerField: this[
            customersViewActions.updateSelectedCustomerField
          ],
          updateDatabase: this.editCustomer,
          showCannotEditPhoneNumberAlert: this.showCannotEditPhoneNumberAlert,
          track: this.$track,
        }
      )
    },
  },
  methods: {
    ...mapActions('customersView', [
      customersViewActions.updateSelectedCustomerField,
    ]),
    ...mapActions('customers', [customersActions.editCustomerField]),
    ...mapActions('loyaltyProgram', [
      loyaltyProgramActions.updateEnrolledCustomerByProperties,
    ]),
    editCustomer(data) {
      rendererEventsService.send(CUSTOMERS_DB_API_EVENTS.channel, {
        event: CUSTOMERS_DB_API_EVENTS.events.updateById.name,
        data,
      })
    },
    showCannotEditPhoneNumberAlert() {
      notificationsService.showError(
        'customersView.customerDetails.errorEditPhone',
        this.$vuetify.lang
      )
    },
    updateCustomerFromList() {
      this[customersActions.editCustomerField](
        this.customerDetailDialog.customerSelected
      )
    },
    updateEnrolledCustomer() {
      this[loyaltyProgramActions.updateEnrolledCustomerByProperties]({
        customerId: this.customerDetailDialog.customerSelected.id,
        customer: this.customerDetailDialog.customerSelected,
      })
    },
  },
  mounted() {
    if (testMode) return
    this.isEnrolledCustomer = this.enrolledCustomers.some(
      enrolledCustomer =>
        enrolledCustomer.customer.id ===
        this.customerDetailDialog.customerSelected.id
    )
    rendererEventsService.subscribe(
      CUSTOMERS_DB_API_EVENTS.replyChannel,
      (event, payload) => {
        if (
          payload.event ===
          CUSTOMERS_DB_API_EVENTS.events.updateById.replies.success
        ) {
          rendererEventsService.send(SYNCHRONIZATION_EVENTS.channel, {
            event: SYNCHRONIZATION_EVENTS.events.createOperation.name,
            data: {
              entityData: JSON.parse(JSON.stringify(payload.data)),
              entityName: 'customers',
            },
          })
          this.updateCustomerFromList()
          this.updateEnrolledCustomer()
        }
      }
    )
  },
  beforeDestroy() {
    rendererEventsService.removeAllListeners(
      CUSTOMERS_DB_API_EVENTS.replyChannel
    )
  },
}
</script>

<style lang="scss" scoped>
.rounded-widget {
  border-radius: 8px;
  .widget-title {
    background-color: var(--v-accentLight-base);
  }
}
</style>
