import { customer as customerMapper } from '@/config/storeMapper'

import { mapStoreObject } from '@/tools/data'
import {
  formatNumberFromDb,
  formatNumberToDb,
  formatNumberToCurrency,
} from '@/tools/numbersFormat'
import { validatePhoneNumber } from '@/tools/customValidations'

import SingleEditDataWidget from '@/components/shared/SingleEditDataWidget'

const setConfig = (state, methods) => ({
  state,
  methods,
  singleWidgets: [
    [
      {
        id: 'name',
        type: SingleEditDataWidget,
        value: state.name,
        valueTextColor: 'textPrimary',
        editTextColor: 'customerPrimary',
        label: 'customersView.addCustomerDialog.name',
        labelIcon: 'mdi-pencil',
        iconColor: 'accent',
        onInputChange: newValue => {
          state.name = newValue.trim()
        },
        onInputFinishEdit: () => {
          if (state.name === '') {
            state.name = state.customer.name
            return
          }
          methods.updateSelectedCustomerField({
            field: 'name',
            value: state.name,
          })
          methods.updateDatabase({
            id: state.customer.id,
            data: mapStoreObject({ name: state.name }, customerMapper, true),
          })
          methods.track({
            type: 'interaction',
            action: 'click',
            category: 'Customers',
            screen: 'CustomerDetails',
            name: 'Save customer name',
          })
        },
        textFormatter: value => value.toString(),
      },
      {
        id: 'address',
        type: SingleEditDataWidget,
        value: state.customer.address,
        valueTextColor: 'textPrimary',
        editTextColor: 'customerPrimary',
        label: 'customersView.addCustomerDialog.address',
        labelIcon: 'mdi-pencil',
        iconColor: 'accent',
        onInputChange: newValue =>
          methods.updateSelectedCustomerField({
            field: 'address',
            value: newValue,
          }),
        onInputFinishEdit: () => {
          methods.updateDatabase({
            id: state.customer.id,
            data: mapStoreObject(
              { address: state.customer.address },
              customerMapper,
              true
            ),
          })
          methods.track({
            type: 'interaction',
            action: 'click',
            category: 'Customers',
            screen: 'CustomerDetails',
            name: 'Save customer address',
          })
        },
        textFormatter: value => {
          return value === undefined || value === null || value.length < 1
            ? '-'
            : value.toString()
        },
      },
    ],
    [
      {
        id: 'phonenumber',
        type: SingleEditDataWidget,
        value: state.phoneNumber,
        valueTextColor: 'textPrimary',
        editTextColor: 'customerPrimary',
        editTextType: 'number',
        label: 'customersView.addCustomerDialog.phone',
        labelIcon: 'mdi-pencil',
        iconColor: 'accent',
        onInputChange: newValue => {
          state.phoneNumber = newValue
        },
        onInputFinishEdit: () => {
          if (!validatePhoneNumberIfIsEnrolledCustomer(state)) {
            methods.showCannotEditPhoneNumberAlert()
            state.phoneNumber = state.customer.phone
            return
          }
          methods.updateSelectedCustomerField({
            field: 'phone',
            value: state.phoneNumber,
          })
          methods.updateDatabase({
            id: state.customer.id,
            data: mapStoreObject(
              { phone: state.phoneNumber },
              customerMapper,
              true
            ),
          })
          methods.track({
            type: 'interaction',
            action: 'click',
            category: 'Customers',
            screen: 'CustomerDetails',
            name: 'Save customer phone',
          })
        },
        textFormatter: value => {
          return value === undefined || value === null || value.length < 1
            ? '-'
            : value.toString()
        },
      },
      {
        id: 'email',
        type: SingleEditDataWidget,
        value: state.customer.email,
        valueTextColor: 'textPrimary',
        editTextColor: 'customerPrimary',
        editTextType: 'email',
        label: 'customersView.addCustomerDialog.email',
        labelIcon: 'mdi-pencil',
        iconColor: 'accent',
        reverse: true,
        onInputChange: newValue =>
          methods.updateSelectedCustomerField({
            field: 'email',
            value: newValue,
          }),
        onInputFinishEdit: () => {
          methods.updateDatabase({
            id: state.customer.id,
            data: mapStoreObject(
              { email: state.customer.email },
              customerMapper,
              true
            ),
          })
          methods.track({
            type: 'interaction',
            action: 'click',
            category: 'Customers',
            screen: 'CustomerDetails',
            name: 'Save customer email',
          })
        },
        textFormatter: value => {
          return value === undefined || value === null || value.length < 1
            ? '-'
            : value.toString()
        },
      },
    ],
    [
      {
        id: 'debtLimit',
        type: SingleEditDataWidget,
        value: state.customer.debtLimit,
        valueTextColor: 'textPrimary',
        editTextColor: 'customerPrimary',
        editTextType: 'number',
        label: 'customersView.addCustomerDialog.debtLimit',
        labelIcon: 'mdi-pencil',
        iconColor: 'accent',
        onInputChange: newValue =>
          methods.updateSelectedCustomerField({
            field: 'debtLimit',
            value: newValue > 0 ? formatNumberToDb(newValue) : 0,
          }),
        onInputFinishEdit: () => {
          methods.updateDatabase({
            id: state.customer.id,
            data: mapStoreObject(
              {
                debtLimit:
                  state.customer.debtLimit > 0 ? state.customer.debtLimit : 0,
              },
              customerMapper,
              true
            ),
          })
          methods.track({
            type: 'interaction',
            action: 'click',
            category: 'Customers',
            screen: 'CustomerDetails',
            name: 'Save customer debt limit',
          })
        },
        numberFormatter: value => (value > 0 ? formatNumberFromDb(value) : ''),
        textFormatter: value =>
          value === undefined || value === null || value.length < 1
            ? '-'
            : formatNumberToCurrency(value),
      },
    ],
  ],
})

const validatePhoneNumberIfIsEnrolledCustomer = state => {
  if (
    !state.isEnrolledCustomer ||
    (!state.phoneNumber && !state.customer.phone)
  ) {
    return true
  }
  return validatePhoneNumber(state.phoneNumber)
}

export default setConfig
