<template>
  <div class="fill-height px-3">
    <PaginatedList :config="tableComponentConfig" />
    <CustomerDetail v-if="customerDetailDialog.isOpen" />
  </div>
</template>

<script>
import { mapState, mapActions, mapGetters } from 'vuex'

import customersViewActions from '@/store/customersView/actions.types'

import setConfig from '@/components/CustomersView/CustomersList/PaginatedTable/config'

import PaginatedList from '@/components/shared/PaginatedTable'
import CustomerDetail from '@/components/CustomersView/CustomerDetail'

export default {
  name: 'PaginatedTableList',
  components: { PaginatedList, CustomerDetail },
  computed: {
    ...mapState('app', ['windowSize']),
    ...mapState('customersView', ['customerDetailDialog']),
    ...mapGetters('customers', ['getFilteredData']),
    tableComponentConfig() {
      return setConfig(
        {
          items: this.getFilteredData,
          windowHeight: this.windowSize.y,
        },
        {
          context: this,
          openCustomerDetailDialog: this.openCustomerDetailDialog,
        }
      )
    },
  },
  methods: {
    ...mapActions('customersView', [
      customersViewActions.setCustomerDetailDialogStatus,
    ]),
    openCustomerDetailDialog(client) {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'Customers',
        screen: 'PaginatedTable',
        name: 'Open customer details',
      })
      const data = {
        isOpen: true,
        selectedCustomer: client,
      }
      this[customersViewActions.setCustomerDetailDialogStatus](data)
    },
  },
}
</script>
