<template>
  <DialogCard :config="dialogConfig.dialogData">
    <Form :config="dialogConfig" />
  </DialogCard>
</template>

<script>
import { mapState, mapActions } from 'vuex'

import { testMode } from '@/config/env'
import CUSTOMERS_DB_API_EVENTS from '@/config/events/databaseAPI/customersEvents'

import { cleanObjectObserver } from '@/tools/data'
import { formatNumberToDb, formatNumberFromDb } from '@/tools/numbersFormat'
import { formatNumberToCurrency } from '@/tools/numbersFormat'

import rendererEventsService from '@/services/renderer/rendererEvents'
import notificationsService from '@/services/renderer/notifications'

import appActions from '@/store/app/actions.types'
import customersActions from '@/store/customers/actions.types'
import customersViewActions from '@/store/customersView/actions.types'
import usersViewActions from '@/store/usersView/actions.types'

import setDialogConfig from '@/components/CustomersView/CustomerDetail/Footer/SettleDebtDialog/config'
import DialogCard from '@/components/shared/DialogCard'
import Form from '@/components/shared/Form'

export default {
  name: 'SettleDebtDialog',
  components: { DialogCard, Form },
  data() {
    return {
      inputs: {},
      validators: { inputs: {} },
      settlingDebt: false,
    }
  },
  computed: {
    ...mapState('customersView', ['settleDebtDialog', 'customerDetailDialog']),
    ...mapState('usersView', ['selectedUser', 'estimatedCash']),
    dialogConfig() {
      return setDialogConfig(
        {
          opened: this.settleDebtDialog.isOpen,
          inputs: this.inputs,
          v: this.$v.inputs,
          customer: this.customerDetailDialog.customerSelected,
        },
        {
          closeDialog: this.closeDialog,
          settleDebt: this.settleDebt,
          track: this.$track,
        }
      )
    },
  },
  methods: {
    ...mapActions('app', [appActions.addPendingSyncOperation]),
    ...mapActions('customers', [customersActions.settleGeneralDebt]),
    ...mapActions('customersView', [
      customersViewActions.setSettleDebtDialogStatus,
      customersViewActions.setCustomerDetailDialogStatus,
    ]),
    ...mapActions('usersView', [usersViewActions.setUserEstimatedCash]),
    setProperties() {
      this.dialogConfig.fields.forEach(field => {
        this.$set(this.inputs, field.id, '')
        if (field.validators)
          this.$set(this.validators.inputs, field.id, {
            ...cleanObjectObserver(field.validators),
          })
      })
    },
    getEstimatedCash() {
      const stateEstimatedCash =
        this.estimatedCash === null || this.estimatedCash === undefined
          ? 0
          : this.estimatedCash
      return formatNumberToDb(stateEstimatedCash)
    },
    closeDialog() {
      Object.keys(this.inputs).forEach(key => this.$v.inputs[key].$reset())
      Object.keys(this.inputs).forEach(key => (this.inputs[key] = ''))
      this[customersViewActions.setSettleDebtDialogStatus](false)
    },
    customersListener(event, payload) {
      const settleGeneralDebtReplies =
        CUSTOMERS_DB_API_EVENTS.events.settleGeneralDebt.replies
      const replies = {
        [settleGeneralDebtReplies.success]: () =>
          this.onGeneralDebtSettled(payload.data),
        [settleGeneralDebtReplies.error]: () =>
          this.onGeneralDebtSettledError(),
      }
      if (payload.event in replies) replies[payload.event]()
    },
    settleDebt() {
      if (this.settlingDebt === true) return
      if (this.$v.inputs.$invalid) {
        Object.keys(this.inputs).forEach(key => this.$v.inputs[key].$touch())
        return
      }
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'Customers',
        screen: 'SettleGeneralDebt',
        name: 'Settle general debt',
      })
      this.settlingDebt = true
      rendererEventsService.send(CUSTOMERS_DB_API_EVENTS.channel, {
        event: CUSTOMERS_DB_API_EVENTS.events.settleGeneralDebt.name,
        data: {
          customer: this.customerDetailDialog.customerSelected,
          amount: formatNumberToDb(this.inputs.settleGeneralDebtAmount),
          user: this.selectedUser.id,
          estimatedCash: this.getEstimatedCash(),
        },
      })
    },
    onGeneralDebtSettled(data) {
      this[appActions.addPendingSyncOperation]()
      this[customersActions.settleGeneralDebt](data.customer)
      this[usersViewActions.setUserEstimatedCash](
        formatNumberFromDb(data.estimatedCash)
      )
      notificationsService.showSuccess(
        'customersView.settleDebtDialog.debtSettled',
        this.$vuetify.lang,
        {},
        [formatNumberToCurrency(this.inputs.settleGeneralDebtAmount)]
      )
      this.closeDialog()
      this[customersViewActions.setCustomerDetailDialogStatus]({
        isOpen: false,
      })
      this.settlingDebt = false
      this.$track({
        type: 'system',
        action: 'settle_general_debt',
        category: 'Customers',
        screen: 'SettleGeneralDebt',
        name: 'Close dialog',
      })
    },
    onGeneralDebtSettledError() {
      this.$track({
        type: 'system',
        action: 'error',
        category: 'Customers',
        screen: 'SettleGeneralDebt',
        name: 'Error settling general debt',
      })
      notificationsService.showError(
        'customersView.settleDebtDialog.errorSettlingDebt',
        this.$vuetify.lang
      )
      this.settlingDebt = false
    },
  },
  validations() {
    return this.validators
  },
  created() {
    if (testMode) return
    rendererEventsService.subscribe(
      CUSTOMERS_DB_API_EVENTS.replyChannel,
      this.customersListener
    )
  },
  mounted() {
    this.setProperties()
  },
  beforeDestroy() {
    rendererEventsService.removeListener(
      CUSTOMERS_DB_API_EVENTS.replyChannel,
      this.customersListener
    )
  },
}
</script>
